<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {localClient,selectedModel,localReady,chooseModel} from '../localClient'
import {useRoute,useRouter} from 'vue-router'
import AppIcon from '../components/AppIcon.vue'
import StatusBadge from '../components/StatusBadge.vue'
import RunReport from '../components/RunReport.vue'
import MarkdownText from '../components/MarkdownText.vue'
import ChatAttachment from '../components/ChatAttachment.vue'
import NetworkPanel from '../components/NetworkPanel.vue'
import type {AgentTask,PermissionMode,CaptureLevel,ChatAttachment as Attachment} from '../types'
import {state,startTask,sendMessage,cancelTask,resumeTask,notify,uploadChatAttachment,setTaskPermission} from '../store'
import ToolActivity from '../components/ToolActivity.vue'
import {shortTitle,dateTime,toolLabel} from '../uiHelpers'
const route=useRoute(),router=useRouter()
const task=computed(()=>state.tasks.find(t=>t.id===route.params.id))
const messages=computed(()=>task.value?.messages??[])
const runs=computed(()=>state.runs.filter(r=>task.value?.runIds.includes(r.id)))
const cases=computed(()=>state.cases.filter(c=>task.value?.caseIds.includes(c.id)))
const input=ref(''),environment=ref(''),submitting=ref(false),showArtifacts=ref(false),artifactTab=ref('cases'),selectedRun=ref(''),query=ref('')
const permissionMode=ref<PermissionMode>('auto'),changingPermission=ref(false),executionSettingsOpen=ref(false)
const modeHelp=computed(()=>permissionMode.value==='readonly'?'只读取现有资料；不保存、不启动测试、不操作浏览器或设备。':permissionMode.value==='bypass'?'范围内的操作免确认；项目边界、容器隔离与资源上限仍有效。':'由 AI 根据你的要求和本次参数判断：执行、询问或拒绝。')
async function changePermission(){if(!task.value)return;changingPermission.value=true;try{await setTaskPermission(task.value.id,permissionMode.value)}catch(e){notify(String(e));permissionMode.value=task.value.permissionMode||'auto'}finally{changingPermission.value=false}}
watch(()=>task.value?.permissionMode,v=>{permissionMode.value=v||'auto'},{immediate:true})
const networkLevel=ref<CaptureLevel|null>(null),openNetworks=ref<string[]>([])
function toggleNetwork(event:Event,id:string){const open=(event.target as HTMLDetailsElement).open;openNetworks.value=open?[...openNetworks.value.filter(v=>v!==id),id]:openNetworks.value.filter(v=>v!==id)}
const historyOpen=ref(false),composerInput=ref<HTMLTextAreaElement|null>(null)
const attachments=ref<Attachment[]>([]),uploading=ref(false),uploadName=ref(''),fileInput=ref<HTMLInputElement|null>(null)
let draftVersion=0
async function addFiles(files:FileList|null){if(!files||uploading.value||submitting.value)return;if(attachments.value.length+files.length>5){notify('每条消息最多 5 个附件');return}const version=draftVersion;uploading.value=true;try{for(const file of Array.from(files)){uploadName.value=file.name;try{const result=await uploadChatAttachment(file);if(version!==draftVersion)break;attachments.value.push(result)}catch(e){notify(file.name+'：'+String(e))}}}finally{uploading.value=false;uploadName.value='';if(fileInput.value)fileInput.value.value=''}}
function pickFiles(e:Event){void addFiles((e.target as HTMLInputElement).files)}
function dropFiles(e:DragEvent){void addFiles(e.dataTransfer?.files??null)}
const active=computed(()=>!!task.value&&['running','queued'].includes(task.value.status))
const history=computed(()=>state.tasks.filter(t=>t.title.toLowerCase().includes(query.value.toLowerCase())))
const currentRun=computed(()=>runs.value.find(r=>r.id===selectedRun.value)??runs.value[0])
function eventFor(id:string){return task.value?.events.find(e=>e.id===id)}
async function send(){if((!input.value.trim()&&!attachments.value.length)||submitting.value||uploading.value)return;submitting.value=true;const text=input.value.trim(),attachmentIds=attachments.value.map(a=>a.id);try{if(task.value)await sendMessage(task.value.id,text,attachmentIds,networkLevel.value);else{const id=await startTask(text,environment.value||state.environments[0]?.id||'',attachmentIds,networkLevel.value,permissionMode.value);await router.push('/agent/'+id)}input.value='';attachments.value=[];networkLevel.value=null}catch(e){notify(String(e))}finally{submitting.value=false}}
function keydown(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void send()}}
type Message=NonNullable<AgentTask['messages']>[number]
const turns=computed(()=>{const list:{id:string;user?:Message;activity:Message[];answer?:Message}[]=[];for(const message of messages.value){if(message.role==='user')list.push({id:message.id,user:message,activity:[]});else{if(!list.length)list.push({id:message.id,activity:[]});list.at(-1)!.activity.push(message)}}for(const [index,turn] of list.entries()){if(turn.activity.at(-1)?.role==='assistant'&&(index<list.length-1||!active.value))turn.answer=turn.activity.pop()}return list})
function activityTitle(activity:Message[]){const labels=[...new Set(activity.filter(m=>m.role==='tool').map(m=>toolLabel(eventFor(m.eventId||m.id)?.name||'')))];return labels.slice(0,3).join(' → ')+(labels.length>3?'…':'')||'执行说明'}
function toolCount(activity:Message[]){return activity.filter(m=>m.role==='tool').length}
function hasToolError(activity:Message[]){return activity.some(m=>m.role==='tool'&&eventFor(m.eventId||m.id)?.status&&['error','waiting_approval','blocked'].includes(eventFor(m.eventId||m.id)?.status||''))}
function sizeComposer(){nextTick(()=>{if(composerInput.value){composerInput.value.style.height='auto';composerInput.value.style.height=Math.min(160,composerInput.value.scrollHeight)+'px'}})}
watch(input,sizeComposer)
const bottom=ref<HTMLElement|null>(null),thread=ref<HTMLElement|null>(null)
watch(()=>messages.value.length,async(_,previous)=>{const near=!thread.value||thread.value.scrollHeight-thread.value.scrollTop-thread.value.clientHeight<180;await nextTick();if(near)bottom.value?.scrollIntoView({behavior:previous===undefined?'auto':'smooth',block:'end'})},{immediate:true})
watch(()=>route.params.id,async()=>{await nextTick();bottom.value?.scrollIntoView({block:'end'})})
watch(()=>[route.params.id,state.projectId],()=>{draftVersion++;input.value='';attachments.value=[];showArtifacts.value=false;selectedRun.value='';historyOpen.value=false;networkLevel.value=null;sizeComposer()})
</script>
<template><div @keydown.esc="showArtifacts=false;historyOpen=false;executionSettingsOpen=false" class="chat-workbench" :class="{'with-artifacts':showArtifacts}">
<button v-if="historyOpen" class="history-backdrop" aria-label="关闭会话列表" @click="historyOpen=false"/>
<aside class="chat-history" :class="{'is-open':historyOpen}"><div class="history-title"><strong>对话记录</strong><button class="icon-button" aria-label="关闭会话列表" @click="historyOpen=false"><AppIcon name="close" :size="16"/></button></div><button class="button secondary full-width" @click="router.push('/agent');historyOpen=false"><AppIcon name="plus" :size="16"/>新建对话</button><input v-model="query" aria-label="搜索对话" placeholder="搜索对话" class="history-search"/><RouterLink v-for="t in history" :key="t.id" :to="'/agent/'+t.id" class="history-entry" :class="{active:task?.id===t.id}" :title="t.title" @click="historyOpen=false"><strong>{{shortTitle(t.title)}}</strong><small>{{dateTime(t.messages?.at(-1)?.createdAt||t.createdAt)}}<span v-if="['running','queued','waiting_approval'].includes(t.status)" class="history-running"> · {{t.status==='running'?'执行中':t.status==='waiting_approval'?'等待确认':'排队中'}}</span></small></RouterLink><p v-if="!history.length" class="form-hint">{{query?'没有匹配的对话':'当前项目还没有对话。'}}</p></aside>
<section class="chat-main"><header class="chat-header"><button class="icon-button history-toggle" aria-label="打开会话列表" @click="historyOpen=!historyOpen"><AppIcon name="menu" :size="18"/></button><div class="chat-title"><h1 :title="task?.title">{{task?shortTitle(task.title):'新对话'}}</h1><span class="muted">{{task?task.environment:state.projectName}}</span></div><div class="chat-header-actions"><details v-if="task" class="chat-runtime"><summary>对话详情</summary><div><p>{{messages.filter(m=>m.role==='user').length}} 次提问 · {{task.rounds}} 次模型决策</p><p>{{task.events.length}} 次工具调用 · {{task.usage?.totalTokens.toLocaleString()||0}} tokens</p><p v-if="task.approvalUsage?.requests">权限判断：{{task.approvalUsage.requests}} 次模型调用<span v-if="task.approvalUsage.reportedCalls"> · 已报告 {{task.approvalUsage.totalTokens.toLocaleString()}} tokens</span><span v-if="(task.approvalUsage.reportedCalls||0)<task.approvalUsage.requests"> · 部分用量未返回</span></p><p v-if="task.extensions">{{task.extensions.skills.length}} 个 Skill · {{task.extensions.mcp.length}} 个 MCP</p><RouterLink to="/settings?tab=skills">管理 Agent 能力</RouterLink></div></details><RouterLink v-else class="text-button" to="/settings?tab=skills">能力设置</RouterLink><button v-if="task" class="button secondary" :aria-expanded="showArtifacts" @click="showArtifacts=!showArtifacts"><AppIcon name="file" :size="15"/>结果 {{cases.length+runs.length+(task?.inspections.length||0)}}</button></div></header>
<div ref="thread" class="chat-thread" aria-live="polite"><div v-if="!task" class="chat-welcome"><AppIcon name="cases" :size="30"/><h2>开始一项测试</h2><p>上传需求、讨论测试点，或让 Agent 查看页面并执行验证。</p><div class="chat-suggestions"><button @click="input='根据项目资料，设计几个接口测试用例，先别执行。'"><AppIcon name="api" :size="18"/>设计接口用例</button><button @click="input='观察登录页面，说明哪些测试值得做，先不要执行回归。'"><AppIcon name="web" :size="18"/>观察页面</button><button @click="input='检查当前项目最近失败的测试，分析原因。'"><AppIcon name="search" :size="18"/>分析失败结果</button></div></div>
<section v-for="(turn,index) in turns" :key="turn.id" class="chat-turn"><article v-if="turn.user" class="chat-message user-message"><span class="message-role">你<span v-if="!turn.user.delivered" class="muted"> · 等待处理</span></span><p class="preserve-lines">{{turn.user.content}}</p><small v-if="turn.user.modelProfileId" class="muted">{{localClient.models.find(m=>m.id===turn.user?.modelProfileId)?.name||turn.user.modelProfileId}} · 思考：{{turn.user.reasoningEffort||'默认'}}</small><div v-if="turn.user.attachments?.length" class="message-attachments"><ChatAttachment v-for="a in turn.user.attachments" :key="a.id" :attachment="a"/></div></article><details v-if="turn.activity.length" class="turn-activity" :open="hasToolError(turn.activity)||(active&&index===turns.length-1)"><summary><AppIcon :name="active&&index===turns.length-1?'running':'terminal'" :size="16"/><strong>{{activityTitle(turn.activity)}}</strong><span>{{toolCount(turn.activity)}} 次工具调用</span><AppIcon name="down" :size="14"/></summary><div class="turn-activity-body"><template v-for="m in turn.activity" :key="m.id"><ToolActivity :task-id="task?.id" :approval="task?.approvals?.find(a=>a.callId===eventFor(m.eventId||m.id)?.callId)" v-if="m.role==='tool'&&eventFor(m.eventId||m.id)" :event="eventFor(m.eventId||m.id)!"/><div v-else-if="m.role==='assistant'&&m.content" class="activity-note"><MarkdownText :content="m.content"/></div></template></div></details><article v-if="turn.answer" class="chat-message assistant-message"><span class="message-role"><AppIcon name="sparkles" :size="16"/>TestPilot</span><MarkdownText :content="turn.answer.content||''"/></article></section>
<div v-if="task&&(cases.length||runs.length)" class="chat-results"><div class="section-heading"><strong>相关用例与结果</strong><button class="text-button" @click="showArtifacts=true">查看全部</button></div><RouterLink v-for="c in cases.slice(0,2)" :key="c.id" :to="'/cases/'+c.id" class="chat-result-card"><AppIcon name="cases" :size="18"/><div><strong>{{c.name}}</strong><small>用例 · v{{c.revisions.at(-1)?.number}} · {{c.revisions.at(-1)?.mode==='steps'?'可视化步骤':'原生脚本'}}</small></div><AppIcon name="external" :size="16"/></RouterLink><RouterLink v-for="r in runs.slice(0,2)" :key="r.id" :to="'/runs/'+r.id" class="chat-result-card"><AppIcon name="play" :size="18"/><div><strong>{{state.cases.find(c=>c.id===r.caseId)?.name||r.caseId}}</strong><small>运行报告 · v{{r.revision}} · {{r.duration}}</small></div><StatusBadge :status="r.status"/></RouterLink></div>
<div v-if="task?.status==='waiting_approval'" class="chat-status" role="status"><StatusBadge status="waiting_approval"/><p>{{task.summary}}</p></div><div v-if="active" class="thinking"><AppIcon name="running" :size="16"/>{{task?.summary}}</div><div v-else-if="task&&['error','interrupted','budget_exhausted','cancelled'].includes(task.status)" class="chat-status"><StatusBadge :status="task.status"/><p>{{task.summary}}</p><button v-if="task.status!=='cancelled'" class="text-button" @click="resumeTask(task.id)">从保存的进度继续</button></div><div ref="bottom"/></div>
<form class="chat-composer" @submit.prevent="send" @dragover.prevent @drop.prevent="dropFiles"><div v-if="attachments.length" class="draft-attachments"><ChatAttachment v-for="a in attachments" :key="a.id" :attachment="a" removable @remove="attachments=attachments.filter(item=>item.id!==a.id)"/></div><p v-if="uploading" class="form-hint" role="status">正在上传并解析：{{uploadName}}</p><textarea ref="composerInput" v-model="input" aria-label="发送给 Agent 的消息" :placeholder="active?'补充要求，Agent 会在下一轮决策时读取…':'提问、补充需求，或告诉 Agent 下一步做什么…'" rows="1" maxlength="6000" @keydown="keydown"/><div v-if="executionSettingsOpen" id="composer-execution-settings" class="composer-options">
<div class="section-heading"><h3>执行设置</h3><button type="button" class="icon-button" aria-label="收起执行设置" @click="executionSettingsOpen=false"><AppIcon name="close" :size="16"/></button></div>
<div class="config-grid"><label v-if="!task" class="field-label">运行环境<select v-if="!task" v-model="environment" class="select compact" aria-label="对话运行环境"><option value="">默认环境</option><option v-for="e in state.environments" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label class="field-label">权限模式<select v-model="permissionMode" class="select compact" aria-label="Agent 权限模式" :title="modeHelp" :disabled="changingPermission||submitting" @change="changePermission"><option value="auto">自动 · AI 判断</option><option value="readonly">只读 / 规划</option><option value="bypass">免确认（bypass）</option></select></label><label class="field-label">网络记录<select v-model="networkLevel" class="select compact" aria-label="本轮网络记录" title="只影响本轮后续浏览器操作；关闭时 Agent 不能重开"><option :value="null">网络记录：Agent 自动</option><option value="api">网络记录：接口</option><option value="detailed">网络记录：详细</option><option value="off">网络记录：关闭</option></select></label></div><p class="form-hint">{{modeHelp}}</p><p class="form-hint">网络记录仅针对本轮后续浏览器操作；关闭后 Agent 不能重开。</p></div>
<div class="composer-actions"><input ref="fileInput" type="file" class="sr-only" tabindex="-1" aria-label="选择需求文档" accept=".pdf,.docx,.txt,.md,.csv,.json,.yaml,.yml" multiple @change="pickFiles"/><button class="icon-button attach-button" type="button" aria-label="添加附件" title="上传需求文档，最多 5 个 / 单个 10 MB" :disabled="uploading||submitting||attachments.length>=5" @click="fileInput?.click()"><AppIcon name="file" :size="19"/></button><div class="composer-model-controls"><select v-model="localClient.modelId" class="select compact" aria-label="本轮模型" @change="chooseModel"><option value="">选择模型</option><option v-for="model in localClient.models" :key="model.id" :value="model.id">{{model.name}}{{model.hasKey?'':'（未存密钥）'}}</option></select><select v-model="localClient.effort" class="select compact" aria-label="思考深度" :title="selectedModel?.reasoningSource==='unknown'?'未确认支持的档位，只提供默认':'根据模型目录显示支持的档位'"><option value="">思考：默认</option><option v-for="effort in selectedModel?.reasoningOptions||[]" :key="effort" :value="effort">{{({none:'关闭思考',minimal:'极浅',low:'浅',medium:'中',high:'深',xhigh:'很深',max:'最大'} as any)[effort]}}</option></select></div><div class="composer-submit"><button v-if="active||task?.status==='waiting_approval'" type="button" class="text-button danger" @click="cancelTask(task!.id)">停止</button><button class="button primary" type="submit" :disabled="submitting||uploading||(!input.trim()&&!attachments.length)||!localReady">{{submitting?'发送中':active?'发送补充':'发送'}}<AppIcon name="send" :size="16"/></button></div></div>
<div class="composer-context"><button type="button" class="composer-settings-toggle" :class="{active:executionSettingsOpen}" :aria-expanded="executionSettingsOpen" aria-controls="composer-execution-settings" :title="modeHelp" @click="executionSettingsOpen=!executionSettingsOpen"><AppIcon name="filters" :size="14"/><span>执行设置</span><span class="composer-permission" :class="permissionMode">{{permissionMode==='auto'?'自动 · AI 判断':permissionMode==='readonly'?'只读 / 规划':'免确认'}}{{networkLevel?' · 网络'+({off:'关闭',api:'接口',detailed:'详细'} as any)[networkLevel]:''}}</span><AppIcon name="down" :size="12"/></button><span class="composer-hint">Enter 发送 · Shift+Enter 换行</span></div>
<p v-if="!state.environments.length" class="composer-notice">请先<RouterLink to="/projects">添加运行环境</RouterLink>。</p><p v-if="!localClient.connected" class="composer-notice">执行器未连接，前往<RouterLink to="/environment">运行环境</RouterLink>查看状态。</p><p v-else-if="!selectedModel" class="composer-notice">请先选择一个模型，或前往<RouterLink to="/settings">模型设置</RouterLink>添加配置。</p><p v-else-if="!selectedModel.hasKey" class="composer-notice">当前模型尚未配置 API Key，前往<RouterLink to="/settings">模型设置</RouterLink>填写密钥。</p><p v-else-if="active" class="composer-notice">模型与思考深度的变更对下一条消息生效，当前执行保持原配置。</p></form>
</section>
<div v-if="showArtifacts&&task" class="artifact-backdrop" @click="showArtifacts=false"/>
<aside v-if="showArtifacts&&task" class="chat-artifacts" aria-label="用例与结果"><div class="artifact-panel-title"><strong>用例与结果</strong><button class="icon-button" aria-label="关闭结果面板" @click="showArtifacts=false"><AppIcon name="close" :size="18"/></button></div><div class="artifact-tabs"><button v-for="t in ['cases','runs','observations']" :key="t" :class="{active:artifactTab===t}" @click="artifactTab=t">{{t==='cases'?'用例':t==='runs'?'运行':'页面观察'}}</button></div><div v-if="artifactTab==='cases'" class="generated-cases"><article v-for="c in cases" :key="c.id" class="generated-case"><div><RouterLink :to="'/cases/'+c.id"><strong>{{c.name}}</strong></RouterLink><p>v{{c.revisions.at(-1)?.number}} · {{c.revisions.at(-1)?.mode==='steps'?'可视化步骤':'原生脚本'}}</p></div></article><p v-if="!cases.length" class="empty-state">还没有关联用例</p></div><div v-else-if="artifactTab==='runs'"><select v-model="selectedRun" class="select full-width" aria-label="选择对话运行报告"><option value="">最近运行</option><option v-for="r in runs" :key="r.id" :value="r.id">{{r.id}} · {{r.status}}</option></select><RouterLink v-if="currentRun" :to="'/runs/'+currentRun.id" class="button secondary full-width">打开完整报告</RouterLink><RunReport v-if="currentRun" :key="currentRun.id" :run="currentRun"/><p v-else class="empty-state">还没有运行</p></div><div v-else class="observation-content"><article v-for="i in task.inspections" :key="i.id"><MarkdownText :content="i.summary"/><a v-for="a in i.artifacts" :key="a.url" :href="a.url" target="_blank" rel="noopener"><img v-if="a.url.endsWith('.png')" :src="a.url" class="evidence-image" alt="页面观察截图"/><span v-else>{{a.name}}</span></a><details v-if="i.network" class="report-section" @toggle="toggleNetwork($event,i.id)"><summary>网络请求 · {{i.network.count}} 条</summary><NetworkPanel v-if="openNetworks.includes(i.id)" :session-id="i.network.id"/></details></article><p v-if="!task.inspections.length" class="empty-state">还没有页面观察记录</p></div></aside>
</div></template>
